eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   programsList: () => (/* binding */ programsList)\n/* harmony export */ });\nconst programsList = [\n    {\n        slug: \"accessibility\",\n        title: \"Accessibility\",\n        image: \"/images/accessibility/accessibility-inauguration-ceremony.jpg\",\n        summary: \"Sangati Durlabh Shauchalaya accessible toilets, railway hub transformations, tactile paving, and public space audits.\",\n        fullContent: `Sangati Foundation tears down physical and infrastructural barriers across public transit, highway toilets, and community spaces. In collaboration with Yatra and Anuprayaas, we made Hazrat Nizamuddin railway station accessible for both locomotor and visual disabilities. On 3 December 2020 (International Day of Persons with Disabilities), we inaugurated our first \"Sangati Durlabh Shauchalaya\" wheelchair-accessible public toilet in Sector 29, Gurgaon. We are actively expanding our campaign to build over 100 accessible highway toilets across India.`,\n        highlights: [\n            \"Sangati Durlabh Shauchalaya: Wheelchair-accessible public toilets launched Sector 29, Gurgaon (3 Dec 2020)\",\n            \"Hazrat Nizamuddin Railway Station: Accessible transit transformation for locomotor & visual disabilities\",\n            \"100+ Highway Accessible Toilets Drive across national highways\",\n            \"Ramp design, tactile paving, grab bar installation, and universal accessibility audits\"\n        ],\n        keyStats: [\n            \"Sector 29 Gurgaon Toilet\",\n            \"100+ Toilet Drive\",\n            \"Hazrat Nizamuddin Hub\"\n        ],\n        partners: [\n            \"Yatra\",\n            \"Anuprayaas\",\n            \"Sangati Mobility Network\"\n        ],\n        gallery: [\n            {\n                id: \"acc-1\",\n                title: \"Sector 29 Gurgaon Accessible Toilet Inauguration Ceremony\",\n                src: \"/images/accessibility/accessibility-inauguration-ceremony.jpg\",\n                caption: \"Ribbon-cutting launch ceremony of Sangati Durlabh Shauchalaya on 3 Dec 2020 (International Day of Persons with Disabilities).\"\n            },\n            {\n                id: \"acc-2\",\n                title: \"Sangati Durlabh Shauchalaya Accessible Toilet Cabin\",\n                src: \"/images/accessibility/accessibility-durlabh-shauchalaya.jpg\",\n                caption: \"Outdoor wheelchair-accessible toilet cabin with custom ramps and grab bars deployed by Sangati Foundation.\"\n            },\n            {\n                id: \"acc-3\",\n                title: \"Universal Accessible Toilet Signage & Branding\",\n                src: \"/images/accessibility/accessibility-toilet-signage.jpg\",\n                caption: \"Universal male, female, and wheelchair accessibility signage on Sangati Foundation public facilities.\"\n            }\n        ]\n    },\n    {\n        slug: \"mobility\",\n        title: \"Mobility\",\n        image: \"/images/programs/program-mobility.jpg\",\n        summary: \"Modified vehicles, folding ramps, accessible cabs, and Nomads on Wheels to unlock independent travel.\",\n        fullContent: `Modified vehicles, folding ramps, wheelchair-accessible cabs, and Nomads on Wheels — our campaign to make tourism across India genuinely reachable. Travel options, boarding, lodging, restaurants, markets, theatres, monuments: each one checked for accessibility and sensitised to the need.`,\n        highlights: [\n            \"Nomads on Wheels: Nationwide accessible tourism campaign\",\n            \"Custom vehicle retrofitting and hand-controls advocacy\",\n            \"Accessible transport directory: hotels, restaurants, theatres, monuments\",\n            \"Door-to-door wheelchair folding ramp provision\"\n        ],\n        keyStats: [\n            \"6,500 km Yatra Route Covered\",\n            \"100s of Verified Accessible Sites\",\n            \"24/7 Helpline Support\"\n        ],\n        partners: [\n            \"Nomads on Wheels\",\n            \"Sangati Mobility Network\"\n        ]\n    },\n    {\n        slug: \"health\",\n        title: \"Health & Critical Care\",\n        image: \"/images/health/health-cancer-van-team.jpg\",\n        summary: \"Rural OPD care in Himachal Pradesh, Asha Kiran mobile cancer screening camps, mammography, and medical aid.\",\n        fullContent: `Sangati Foundation organizes free cancer screening, health check-up, and awareness camps in partnership with the Indian Cancer Society, IDSIL, and Engineers India Limited (EIL). Utilizing the Asha Kiran Mobile Cancer Detection Van equipped with digital X-ray, mammography, and diagnostic facilities, we screen rural and marginalized populations. Our critical care center in Bathri, Dalhousie, HP also serves 300 OPD patients daily with consultation, maternal care, and emergency aid.`,\n        highlights: [\n            \"Asha Kiran Mobile Cancer Detection Van: Mammography, Pap Smear, Digital X-Ray, & ENT checks\",\n            \"Free Cancer Screening & Awareness Camps in partnership with Indian Cancer Society & IDSIL\",\n            \"Winter Warmth & Relief Drives: Distribution of warm sweaters, blankets, and essential winter wear to wheelchair users & PwD families\",\n            \"Bathri Critical Care Centre (Dalhousie, HP): 300 OPD patients served daily\",\n            \"Specialized focus on women health (over 80% female beneficiaries in screening camps)\"\n        ],\n        keyStats: [\n            \"300 Daily OPD Patients\",\n            \"140+ Cancer Screenings\",\n            \"Winter Warmth Drives\"\n        ],\n        partners: [\n            \"Indian Cancer Society\",\n            \"Engineers India Limited (EIL)\",\n            \"Disabled Employees Assoc. of Railways\",\n            \"IDSIL\"\n        ],\n        gallery: [\n            {\n                id: \"hl-1\",\n                title: \"Asha Kiran Mobile Cancer Detection Van & Sangati Team\",\n                src: \"/images/health/health-cancer-van-team.jpg\",\n                caption: \"Sangati Foundation volunteers and doctors in front of the Asha Kiran Mobile Cancer Detection Van during the screening drive.\"\n            },\n            {\n                id: \"hl-2\",\n                title: \"Winter Sweater & Blanket Giveaway for Wheelchair Users\",\n                src: \"/images/health/health-winter-blanket-wheelchair.jpg\",\n                caption: \"Sangati representative handing warm winter blankets and sweaters directly to a wheelchair beneficiary (Disabled Employees Assoc. of Railways).\"\n            },\n            {\n                id: \"hl-3\",\n                title: \"Winter Relief Distribution Drive for PwD Families\",\n                src: \"/images/health/health-winter-relief-distribution.jpg\",\n                caption: \"Sangati team distributing stacks of colorful warm winter blankets, shawls, and sweaters at an outdoor community relief drive.\"\n            },\n            {\n                id: \"hl-4\",\n                title: \"Winter Warmth Relief Preparation & Stacks\",\n                src: \"/images/health/health-winter-blankets-stack.jpg\",\n                caption: \"Stacks of warm winter blankets and sweaters organized for distribution to PwD beneficiaries.\"\n            },\n            {\n                id: \"hl-5\",\n                title: \"Doctor Performing OPD Medical Examination\",\n                src: \"/images/health/health-opd-checkup.jpg\",\n                caption: \"Medical doctor examining a patient during the free rural health check-up camp.\"\n            },\n            {\n                id: \"hl-6\",\n                title: \"Sangati Free Cancer Screening & Awareness Camp Team\",\n                src: \"/images/health/health-camp-banner-group.jpg\",\n                caption: \"Group photo of Sangati Foundation, Indian Cancer Society, and IDSIL volunteers at the medical camp.\"\n            },\n            {\n                id: \"hl-7\",\n                title: \"Accessible Asha Kiran Mobile Medical Van with Ramp\",\n                src: \"/images/health/health-mobile-van-ramp.jpg\",\n                caption: \"The wheel-accessible Asha Kiran Cancer Detection Mobile Van equipped for specialized diagnostic screenings.\"\n            }\n        ]\n    },\n    {\n        slug: \"skills\",\n        title: \"Skill Development & Jobs\",\n        image: \"/images/skills/skill-bakery-mandi-group.jpg\",\n        summary: \"Project Udaan: Free skill training in Bakery & Culinary Arts, RPL Pump Operator, Laptop Repair, Web Dev, Python, DTP, and placement support.\",\n        fullContent: `Under Project Udaan, Sangati runs free skill development and vocational training for persons with disability (PwD) and Below Poverty Line (BPL) candidates across Himachal Pradesh (Mandi & Kangra) and Delhi NCR. Initiatives include Bakery & Pastry Training, RPL Pump Operator Certification under State Sanitation Mission, Laptop Repair with CompTIA A+ certification, Web Development, and DTP. Delivered at our centers with partners including Charities Aid Foundation, State Sanitation Mission HP, and Sh Praveen Vyas (Jodhpur Center). Our job portal helps candidates prepare, interview and secure sustainable livelihoods with ongoing mentorship.`,\n        highlights: [\n            \"Project Udaan Bakery & Pastry Training for PwD & BPL candidates in Mandi (HP)\",\n            \"RPL Pump Operator Training in District Kangra (HP) under State Sanitation Mission\",\n            \"Free certification in Laptop Repair (CompTIA A+), Web Dev, Python, & DTP\",\n            \"Dedicated Job Portal & post-placement mentorship for independent living\"\n        ],\n        keyStats: [\n            \"170+ Certified Trainees\",\n            \"Mandi & Kangra Centers\",\n            \"100% Free Tuition\"\n        ],\n        partners: [\n            \"Charities Aid Foundation\",\n            \"State Sanitation Mission HP\",\n            \"CompTIA\",\n            \"JetKing\"\n        ],\n        gallery: [\n            {\n                id: \"sk-1\",\n                title: \"Project Udaan Bakery Training Graduation (Mandi, HP)\",\n                src: \"/images/skills/skill-bakery-mandi-group.jpg\",\n                caption: \"Group photo of PwD & BPL trainees receiving Sangati Skill Development Certificates in Mandi, Himachal Pradesh.\"\n            },\n            {\n                id: \"sk-2\",\n                title: \"Wheelchair Beneficiary Receiving Bakery Certificate\",\n                src: \"/images/skills/skill-bakery-wheelchair.jpg\",\n                caption: \"Wheelchair beneficiary proudly holding his Bakery & Pastry Training Certificate at Sangati Skill Development Center, Mandi.\"\n            },\n            {\n                id: \"sk-3\",\n                title: \"Sangati Skill Certificate Distribution Ceremony\",\n                src: \"/images/skills/skill-cert-ceremony.png\",\n                caption: \"Women trainees receiving their Sangati Foundation Skill Certificates during the graduation ceremony.\"\n            },\n            {\n                id: \"sk-4\",\n                title: \"Graduating Class of Tech & Repair Skill Trainees\",\n                src: \"/images/skills/skill-classroom-group.jpg\",\n                caption: \"Group photo of young men and women celebrating their skill certification at Sangati Foundation.\"\n            },\n            {\n                id: \"sk-5\",\n                title: \"RPL Pump Operator Training Session (Kangra, HP)\",\n                src: \"/images/skills/skill-kangra-training.png\",\n                caption: \"Classroom training session for Pump Operator certification under State Sanitation Mission in Kangra, Himachal Pradesh.\"\n            }\n        ]\n    },\n    {\n        slug: \"livelihood\",\n        title: \"Livelihood & Entrepreneurship\",\n        image: \"/images/livelihood/ekart-shoppe-sidecar.jpg\",\n        summary: \"Sangati Shoppe (संगTea) custom retrofitted e-karts and mobile vendor carts for PwD economic self-reliance and dignity.\",\n        fullContent: `Sangati Shoppe is a custom-designed, accessible mobile street vendor cart — संगTea — built specifically so that persons with disability (PwD) can own and operate micro-businesses independently and with utmost dignity. Featuring retrofitted motorized 3-wheelers, sidecars, gas stoves, beverage coolers, and commodity display racks, Sangati Foundation partners with Evoo (VentureonWheels) and NHFDC to empower micro-entrepreneurs across urban and rural markets.`,\n        highlights: [\n            \"संगTea / Sangati Shoppe: Custom ergonomic motorized e-karts & sidecars for Divyang entrepreneurs\",\n            \"Turnkey micro-business setup: Built-in tea stoves, beverage coolers, and commodity display racks\",\n            \"Keys handover, licensing guidance, and financial independence mentorship\",\n            \"VentureonWheels partnership with Evoo and NHFDC handicraft showcase at Divyakala Mela\"\n        ],\n        keyStats: [\n            \"Independent E-Kart Businesses\",\n            \"NHFDC Handicraft Partner\",\n            \"VentureonWheels Carts\"\n        ],\n        partners: [\n            \"NHFDC\",\n            \"Evoo (VentureonWheels)\",\n            \"Sangati Shoppe Network\"\n        ],\n        gallery: [\n            {\n                id: \"lv-1\",\n                title: \"Sangati Shoppe Retrofitted Electric Vendor Sidecar Cart\",\n                src: \"/images/livelihood/ekart-shoppe-sidecar.jpg\",\n                caption: \"Micro-entrepreneurs operating their Sangati Shoppe custom retrofitted motorized sidecar vendor cart.\"\n            },\n            {\n                id: \"lv-2\",\n                title: \"संगTea Mobile Cart Keys Handover to Female PwD Entrepreneur\",\n                src: \"/images/livelihood/ekart-sangtea-key-handover.png\",\n                caption: \"Official keys handover ceremony of the sangTea motorized tricycle cart to an empowered female entrepreneur.\"\n            },\n            {\n                id: \"lv-3\",\n                title: \"Sangati Shoppe Ergonomic Mobile Tea & Snack Stall\",\n                src: \"/images/livelihood/ekart-shoppe-tea-stall.jpg\",\n                caption: \"Divyang vendor operating a fully equipped mobile tea stall with gas stove, kettles, and storage shelves.\"\n            },\n            {\n                id: \"lv-4\",\n                title: \"Maroon Motorized 3-Wheel Vendor Cart for Divyang Entrepreneurs\",\n                src: \"/images/livelihood/ekart-shoppe-maroon-trike.jpg\",\n                caption: \"Entrepreneur on his customized maroon motorized 3-wheeler fitted with snack display racks.\"\n            },\n            {\n                id: \"lv-5\",\n                title: \"Sangati Shoppe Accessible Mobile Vendor Unit with Cooler\",\n                src: \"/images/livelihood/ekart-shoppe-street-vendor.png\",\n                caption: \"Street vendor unit featuring Coca-Cola cooler box and hanging commodity display strips on city road.\"\n            }\n        ]\n    },\n    {\n        slug: \"para-sports\",\n        title: \"Para Sports & Adaptive Yoga\",\n        image: \"/images/parasports/parasports-india-gate-yoga.jpg\",\n        summary: \"Accessible Yoga at India Gate with Ministry of Ayush, Wheelchair Cricket Champions, Half-Marathon runners, and adaptive athletics.\",\n        fullContent: `Sangati Foundation actively champions Para Sports, Wheelchair Athletics, and Accessible Fitness across India. On International Yoga Day at India Gate, New Delhi, in collaboration with the Ministry of Ayush (Govt. of India), Eagle Specially Abled Riders, and Kaner Electric Connections, our Divyang athletes and retrofitted scooter riders made history by demonstrating Accessible Yoga (\"सुगम्य योग\"). We also sponsor Wheelchair Cricket tournaments (Delhi Abled & Wheelchair Cricket Warriors), field teams for the Vedanta Delhi Half-Marathon (Champions with Disability segment), and run inclusive athletic clubs.`,\n        highlights: [\n            \"Accessible Yoga at India Gate on International Yoga Day with Ministry of Ayush (Govt. of India)\",\n            'Sugamya Yoga (\"सुगम्य योग\") performed by Divyang athletes on retrofitted scooters and wheelchairs',\n            \"Wheelchair Cricket Warriors: Tournament sponsorship, equipment, and training support\",\n            \"Vedanta Delhi Half-Marathon: 25 Divyang marathon runners representing Sangati Foundation\"\n        ],\n        keyStats: [\n            \"Ministry of Ayush Partner\",\n            \"Wheelchair Cricket Team\",\n            \"25+ Half-Marathon Runners\"\n        ],\n        partners: [\n            \"Ministry of Ayush (Govt. of India)\",\n            \"Eagle Specially Abled Riders\",\n            \"Kaner Electric Connections\",\n            \"Wheelchair Cricket Association\"\n        ],\n        gallery: [\n            {\n                id: \"ps-1\",\n                title: \"Accessible Yoga at India Gate (Ministry of Ayush)\",\n                src: \"/images/parasports/parasports-india-gate-yoga.jpg\",\n                caption: \"Divyang athletes and wheelchair participants performing Accessible Yoga at India Gate on International Yoga Day.\"\n            },\n            {\n                id: \"ps-2\",\n                title: \"Wheelchair Cricket Warriors Tournament\",\n                src: \"/images/parasports/parasports-wheelchair-cricket.jpg\",\n                caption: \"Divyang wheelchair cricket players and coaches shaking hands on the pitch during an official match.\"\n            },\n            {\n                id: \"ps-3\",\n                title: \"National Media Feature: Sugamya Yoga on Retrofitted Scooters\",\n                src: \"/images/parasports/parasports-yoga-news-clipping.jpg\",\n                caption: 'Front-page news feature (\"एक नई क्रांति न्यूज़\") highlighting Accessible Yoga on retrofitted scooters at India Gate.'\n            },\n            {\n                id: \"ps-4\",\n                title: \"Outdoor Accessible Yoga Masterclass Session\",\n                src: \"/images/parasports/parasports-outdoor-yoga-session.png\",\n                caption: \"Yoga Guru Sandeep Kumar conducting an outdoor accessible yoga training session under the trees.\"\n            },\n            {\n                id: \"ps-5\",\n                title: \"Sangati Para Athletes & Retrofitted Scooter Riders Group\",\n                src: \"/images/parasports/parasports-riders-group.jpg\",\n                caption: \"Group photo of Sangati Para Athletes and scooter riders gathering after their yoga and sports session.\"\n            }\n        ]\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./content/programs.ts\n");

